"Washington Oliveira","gestor","Dekker Jordão Baptista",true,"Licitações e Contratos",[3,3,3,2,2,3,3,2,4,2,3,3,2]],["Maísa Rangel","gestor","Dekker Jordão Baptista",true,"Administrativo & Financeiro",[2,3,3,2,3,3,2,4,3,3,3,3,3]],["Mara Fernanda Santos","gestor","Dekker Jordão Baptista",true,"Sucesso de Cliente e Projetos",[2,2,3,2,2,3,3,3,2,2,2,3,3]]],"nps":[["Ana Raquel",10],["Dekker Jordão Baptista",8],["Dekker Jordão Baptista",8],["Dekker Jordão Baptista",9],["Dekker Jordão Baptista",9],["Dekker Jordão Baptista",10],["Dekker Jordão Baptista",10],["Dekker Jordão Baptista",10],["Dekker Jordão Baptista",10],["Dekker Jordão Baptista",10]]}}'::jsonb; t text; it jsonb; a jsonb; vi int; v_it int[]; v_av uuid; k int; nm text;
begin
  if exists (select 1 from gpp.des_avaliacoes where origem = 'importado') then raise exception 'Histórico já importado.'; end if;
  -- pessoas que só existem nas planilhas entram como inativas
  for t in select jsonb_object_keys(d) loop
    for a in select * from jsonb_array_elements(d->t->'av') loop
      foreach nm in array array[a->>0, a->>2] loop
        if nm is not null and not exists (select 1 from gpp.organizadores where nome = nm) then
          insert into gpp.organizadores (nome, ativo, e_lider) values (nm, false, false);
        end if;
      end loop;
    end loop;
  end loop;
  for t in select jsonb_object_keys(d) order by 1 loop
    for a in select * from jsonb_array_elements(d->t->'av') loop
      update gpp.organizadores set gestor_id = (select id from gpp.organizadores where nome = a->>2), e_lider = (a->>3)::boolean
      where nome = a->>0 and ativo = false and gestor_id is null and a->>2 is not null and nome <> a->>2;
    end loop;
    v_it := '{}';
    k := 0;
    for it in select * from jsonb_array_elements(d->t->'itens') loop
      k := k + 1;
      insert into gpp.des_itens (trimestre, ordem, competencia_id, texto, so_lideres)
      values (t, k, (select id from gpp.des_competencias where nome = it->>0), it->>1, (it->>2)::boolean) returning id into vi;
      v_it := v_it || vi;
    end loop;
    for a in select * from jsonb_array_elements(d->t->'av') loop
      insert into gpp.des_avaliacoes (trimestre, avaliado_id, avaliador_id, tipo, e_lider, area, respondida_em, origem)
      values (t, (select id from gpp.organizadores where nome = a->>0),
              (select id from gpp.organizadores where nome = case when a->>1 = 'auto' then a->>0 else a->>2 end),
              a->>1, (a->>3)::boolean, a->>4, ((d->t->>'fim') || ' 12:00-03')::timestamptz, 'importado')
      returning id into v_av;
      insert into gpp.des_notas (avaliacao_id, item_id, nota)
      select v_av, v_it[x.i], x.n::smallint from jsonb_array_elements_text(a->5) with ordinality x(n, i) where x.n is not null;
    end loop;
    insert into gpp.des_nps (trimestre, gestor_id, nota, origem)
    select t, (select id from gpp.organizadores where nome = x->>0), (x->>1)::smallint, 'importado'
    from jsonb_array_elements(d->t->'nps') x;
  end loop;
end $imp$;
